// Shared, independently testable editing geometry.
export function cropRect(im,l){const zoom=l.crop?.zoom||1,scale=Math.max(l.w/im.width,l.h/im.height)*zoom,w=l.w/scale,h=l.h/scale;return {x:(im.width-w)*(l.crop?.x??50)/100,y:(im.height-h)*(l.crop?.y??50)/100,w,h};}
export function transformMembers(layers,before,anchorId){const old=before.find(l=>l.id===anchorId),now=layers.find(l=>l.id===anchorId);if(!old||!now)return;const s=now.w/old.w,a=(now.rotation-old.rotation)*Math.PI/180;for(const original of before){if(original.id===anchorId)continue;const l=layers.find(l=>l.id===original.id);if(!l)continue;const dx=(original.x-old.x)*s,dy=(original.y-old.y)*s;l.x=now.x+dx*Math.cos(a)-dy*Math.sin(a);l.y=now.y+dx*Math.sin(a)+dy*Math.cos(a);l.w=original.w*s;l.h=original.h*s;l.rotation=((original.rotation+a*180/Math.PI+540)%360)-180;if(original.fontSize)l.fontSize=Math.max(8,Math.min(600,original.fontSize*s));}}
